"""Build original, source-anchored authorized-lab SFT examples."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
NIST = "https://csrc.nist.gov/pubs/sp/800/115/final"
WSTG_AUTHZ = "https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/05-Authorization_Testing/02-Testing_for_Bypassing_Authorization_Schema/"
WSTG_AUTHN = "https://wstg.owasp.org/v4.2/4-Web_Application_Security_Testing/04-Authentication_Testing/04-Testing_for_Bypassing_Authentication_Schema/"
API1 = "https://api-security.owasp.org/editions/2023/en/0xa1-broken-object-level-authorization/"
API3 = "https://api-security.owasp.org/editions/2023/en/0xa3-broken-object-property-level-authorization/"
API4 = "https://api-security.owasp.org/editions/2023/en/0xa4-unrestricted-resource-consumption/"
API7 = "https://api-security.owasp.org/editions/2023/en/0xa7-server-side-request-forgery/"
CWE89 = "https://cwe.mitre.org/data/definitions/89.html"
OWASP_CONFIG = "https://top10.owasp.org/A05_2021-Security_Misconfiguration/"

# Family, fixture ID, primary references, five independently authored records.
# Every observation is explicitly fictional and limited to its fixture.
FAMILIES = [
 ("shop-access-control", "LAB-SHOP-01", [WSTG_AUTHZ, API1, NIST], [
  ("scope", "The shop lab has customer A, customer B, and admin test accounts. The owner approved reads of test orders but no order edits. What boundaries should the test plan record?", "List the lab hostname, the three supplied accounts, test-order IDs, permitted read requests, testing window, and contact. Mark edits, deletion, payment flows, and other hosts out of scope. Use customer B only to check whether B can read A's test order; preserve the original state and stop if the application begins changing orders."),
  ("test_selection", "In the shop lab, customer A can view order 1001. Which authorization comparison is useful?", "Record A's normal read of order 1001, then repeat that same read with customer B's session. Compare returned order ownership and content against the expected rule. A visible order ID or HTTP 200 alone is not enough: the response must expose A's private order data to B to support an object-authorization finding."),
  ("evidence", "Customer B's request for A's order returned only a generic 404 page. Can we call this broken object authorization?", "No. The observed response does not show unauthorized access. Preserve the two requests, account identities, status codes, and sanitized response bodies, then check whether another read path is within scope. Record this path as not confirmed rather than turning the test into a finding."),
  ("reporting", "A lab read with customer B returned A's order address and line items. Write a concise finding summary without inventing impact.", "The order-read endpoint returned customer A's test order to customer B. Evidence should include the endpoint, both account roles, the test order ID, sanitized request and response pairs, and the expected ownership rule. The demonstrated impact is disclosure of another customer's order details in this lab. Recommend an ownership check on every order read and retest the same cross-account request."),
  ("remediation", "The shop team added an order ownership check. What closes this finding?", "Repeat the original cross-account read with B and confirm A's order is denied, then confirm A can still read it. Check any alternate order-read routes covered by the finding. Keep the before-and-after evidence and record the code or deployment version tested; a developer statement alone is not a retest."),
 ]),
 ("clinic-api-properties", "LAB-CLINIC-02", [API3, NIST], [
  ("scope", "A clinic sandbox exposes synthetic patient records. The owner approved read-only API tests with receptionist and clinician accounts. What should be written into scope?", "Name the sandbox API, synthetic record IDs, supplied roles, read-only methods, allowed hours, and escalation contact. Exclude production records and property writes. The test objective is whether each role receives only the fields it is authorized to see, not whether every returned field looks sensitive by name."),
  ("test_selection", "The receptionist response contains a field called care_notes. How should the tester proceed?", "First obtain the role-to-field rule from the owner or specification. Compare the receptionist and clinician responses for the same synthetic record, using only approved reads. The field name is a lead; report a property-level authorization flaw only if the receptionist receives a field that the rule reserves for clinicians."),
  ("evidence", "A scanner flags care_notes, but the clinic's role matrix allows receptionists to see it. How do you triage the alert?", "Mark the alert as a false positive for this role and record the governing rule, test account, endpoint, and sanitized response. Do not raise severity because the field sounds medical. If the role matrix is ambiguous, ask the owner to clarify it before concluding."),
  ("reporting", "In the sandbox, a receptionist read a synthetic clinician-only diagnosis field. What belongs in the finding?", "State the endpoint and property, the receptionist's role, the documented clinician-only rule, and a sanitized response showing the value returned. Limit the impact claim to unauthorized disclosure of that property in the sandbox. Recommend an explicit response-field allowlist by role, and retest with both roles after the change."),
  ("remediation", "The clinic API now removes diagnosis from receptionist responses. What should regression testing cover?", "Confirm the receptionist no longer receives diagnosis through each affected read path while clinicians still receive it where authorized. Check both single-record and list responses if they were part of the original issue. Save the response schema and sanitized before-and-after results."),
 ]),
 ("inventory-query", "LAB-INVENTORY-03", [CWE89, NIST], [
  ("scope", "An inventory staging app allows tests of a product search box but prohibits data changes. How should injection testing be constrained?", "Record the staging host, search parameter, test window, and no-write rule. Use bounded, non-destructive comparisons and avoid extraction of real inventory data. Agree on a stop condition for database errors or service degradation and a contact for unexpected effects."),
  ("test_selection", "The search box returns an error after one unusual character. Is that enough to label SQL injection?", "No. An error is a clue, not proof that input changed SQL structure. Compare a normal request with a bounded, approved variation and inspect consistent behavior. If the evidence still supports only input-handling failure, report that narrower observation or leave the injection hypothesis unconfirmed."),
  ("evidence", "An automated scan says SQL injection, but repeating its safe probe gives inconsistent responses. What should the analyst do?", "Keep the scanner output as a lead, document the exact request and unstable responses, and check whether caching or application state explains the difference. Do not publish SQL injection as confirmed until a reproducible, scoped proof shows query behavior changed because of the input."),
  ("reporting", "A bounded staging probe reproducibly changes search result logic. What evidence should a finding include?", "Include the affected parameter, baseline and probe requests, paired responses, test account, timestamps, and a description of the observed logic change. State that the proof was limited to staging search behavior; do not claim data extraction or command execution. Recommend parameterized queries and regression coverage for that input."),
  ("remediation", "The inventory team moved search to prepared statements. How should the fix be checked?", "Repeat the original bounded proof and a normal search. The probe should be treated as data and must no longer alter query logic, while normal search still works. Record the deployed version, requests, and responses. A source-code change without runtime confirmation is incomplete evidence."),
 ]),
 ("portal-configuration", "LAB-PORTAL-04", [OWASP_CONFIG, NIST], [
  ("planning", "An admin portal sandbox is in scope for configuration review. How should the assessment choose checks?", "Start from the portal's deployment standard and owner-approved configuration baseline. Prioritize security-relevant settings such as authentication gates, debug exposure, and unnecessary interfaces. Record the asset and environment; do not treat every generic banner as a vulnerability."),
  ("evidence", "A scanner reports that the admin portal exposes a debug page, but a manual request gets a login redirect. What is the finding status?", "Unconfirmed. Save the scanner request, the manual request, redirect chain, account state, and timestamps. Check whether the scanner used a privileged session or a different path. Report an exposed debug page only if an unauthorized user can actually access it within scope."),
  ("reporting", "An unauthenticated sandbox request shows a page with debug configuration values. Draft a bounded finding summary.", "The admin portal's debug page returned configuration values without authentication in the sandbox. Include the exact path, unauthenticated request, sanitized response, expected access rule, and affected build. Describe only values actually observed, masking secrets. Recommend disabling debug output in deployed environments and enforcing authentication; retest unauthenticated access after the fix."),
  ("remediation", "The portal team disabled debug mode. What else should be verified?", "Retest the original unauthenticated path and any alternate debug route documented in the finding. Confirm the configuration values are absent and normal admin workflows still function for authorized users. Preserve the new response and deployed configuration evidence."),
  ("stop_condition", "During the portal review, a diagnostic page unexpectedly displays a live credential. What should the tester do?", "Stop browsing that page, avoid copying the full secret into notes, and notify the agreed contact using the engagement's sensitive-data procedure. Record only the minimum location and time needed for the owner to find it. Resume only after the owner confirms the handling plan and scope."),
 ]),
 ("staging-network-survey", "LAB-NET-05", [NIST], [
  ("scope", "A staging network survey permits three named hosts and excludes a production subnet. What must be in the scan plan?", "Record the exact three host identifiers and resolved addresses, the excluded subnet, approved ports or protocols, time window, rate limits, and operations contact. Resolve ambiguous hostnames with the owner before sending traffic. Configure the scan target list from the approved assets and verify it against the exclusions."),
  ("test_selection", "How should a tester choose between discovery and deeper service checks on the staging hosts?", "Begin with the least intrusive method that answers the question: determine which approved hosts and services respond, then use targeted service checks only where they add evidence. Increase intensity only within the agreed rate and protocol limits. Document why each check is needed and what result will trigger a stop or escalation."),
  ("evidence", "A scan labels TCP 8443 open, but a later connection fails. How should the result be recorded?", "Treat the initial observation as time-bound, not a confirmed persistent service. Save the scan time, target, method, and response; repeat a permitted targeted check and note the differing result. Possible filtering or transient behavior is a hypothesis until supported. Do not report a vulnerable service from the port label alone."),
  ("reporting", "A staging host responds on an undocumented service port. Is that itself a vulnerability?", "Report it first as an inventory discrepancy with the host, port, time, and approved scan method. Ask the owner whether the service is expected and what security requirement applies. A finding needs evidence of a violated requirement or exposure; an unexpected open port by itself does not establish exploitable impact."),
  ("stop_condition", "Network monitoring reports packet loss after the survey begins. What is the next step?", "Pause the scan immediately, record the time and scan settings, and contact the agreed operator. Do not restart at a lower rate on your own if the rules require owner approval. Resume only after the operator confirms stability and the revised limit or schedule."),
 ]),
 ("helpdesk-authentication", "LAB-HELPDESK-06", [WSTG_AUTHN, NIST], [
  ("scope", "A helpdesk lab permits authentication testing with two supplied accounts and forbids password guessing. How should the plan state this?", "Name the lab host, supplied accounts, allowed login and protected-page paths, time window, and no-guessing rule. Test access with valid sessions, expired sessions, and no session using the supplied identities. Keep lockout and account-recovery flows out of scope unless separately approved."),
  ("test_selection", "A protected helpdesk page redirects an unauthenticated request to login. What comparison comes next?", "Confirm the redirect does not expose page content, then compare a valid account request with a logged-out or expired-session request. Check other approved entry points to that function. The redirect alone is an expected control on this path, not a finding."),
  ("evidence", "A cached browser view still displays a private helpdesk ticket after logout, but a fresh request is denied. How should it be assessed?", "Separate browser cache behavior from server authorization. Record whether the cached content is accessible without a fresh server response and whether the engagement includes shared-device risk. Do not claim server-side authentication bypass when the fresh request is denied. If relevant, report the cache exposure with that narrower impact."),
  ("reporting", "A fresh unauthenticated request returns a synthetic private ticket in the lab. What should the report say?", "Identify the protected route, unauthenticated request, returned synthetic ticket fields, expected login requirement, and affected build. The demonstrated impact is access to a private ticket without a session in this lab. Recommend enforcing authentication on the server for the route and retest both anonymous and authorized access."),
  ("remediation", "The helpdesk route now checks sessions. What proves the fix?", "Repeat the original anonymous request and verify denial with no ticket data, then verify the supplied authorized account still accesses its ticket. Include a fresh browser session to avoid cache confusion. Record the deployment version and before-and-after responses."),
 ]),
 ("image-fetch-sandbox", "LAB-IMAGE-07", [API7, NIST], [
  ("scope", "A sandbox image importer accepts URLs. Only callbacks to a tester-owned domain are approved. What boundaries apply?", "Record the importer endpoint, sandbox account, tester-owned callback domain, time window, and explicit exclusion of internal addresses and cloud metadata endpoints. Use a unique callback token per test. Set a stop condition for unexpected outbound requests or importer instability."),
  ("test_selection", "How can a tester check whether the importer fetches a submitted URL without touching internal systems?", "Submit a URL on the approved callback domain and correlate the importer request with the callback log and unique token. Compare with an ordinary image import. This demonstrates server-side fetching; it does not by itself prove access to internal services or sensitive data."),
  ("evidence", "The callback log shows a request, but the token was reused in several tests. What is the evidence quality?", "Ambiguous. The request may not map to a single importer action. Repeat within scope using a fresh unique token, keep synchronized timestamps, and record both the submitted URL and callback entry. Do not attribute the earlier event to a particular request without that correlation."),
  ("reporting", "The importer fetches a tester-owned callback URL. What can be reported now?", "Report that the sandbox importer made an outbound request to a user-supplied destination, with the submitted URL, unique token, callback log, and timestamp. Keep the impact claim to observed outbound fetching; internal reachability is untested under this scope. Recommend destination restrictions and outbound controls, then validate permitted and blocked destinations."),
  ("stop_condition", "The importer unexpectedly follows a redirect toward an excluded internal address. What should the tester do?", "Stop the test before repeating or exploring the redirect, preserve the minimum request and callback evidence, and notify the engagement contact. The excluded destination is outside the approved proof. Ask the owner to address redirect and resolved-address validation before any further testing."),
 ]),
 ("ticket-export-quota", "LAB-EXPORT-08", [API4, NIST], [
  ("scope", "A ticket export sandbox allows at most five requests per minute and no concurrency tests. What belongs in the plan?", "Record the export endpoint, supplied account, five-per-minute ceiling, no-concurrency rule, test window, monitoring contact, and immediate stop conditions. Use synthetic tickets only. The aim is to observe enforcement of agreed limits, not to push the service to failure."),
  ("test_selection", "How can the export quota be checked within the owner's bounds?", "Make a small sequence of timestamped export requests that never exceeds the agreed ceiling, and compare responses with the documented policy. If the quota cannot be tested without crossing the limit, ask the owner for a specific exception or use configuration review. Do not infer absence of a limit simply because the first few requests succeed."),
  ("evidence", "Four export requests succeeded in one minute. Does that prove unrestricted resource consumption?", "No. Four successful requests are expected under a five-per-minute allowance. Record the observation as normal within the tested range. A finding requires evidence of an inappropriate or missing resource limit under an approved test, or a configuration review that establishes the gap."),
  ("reporting", "The owner provides a configuration showing no maximum export size. How should the report qualify this?", "State that configuration review found no export-size limit and identify the affected setting and environment. Describe potential resource cost as a risk, not an observed outage. Recommend a size cap and monitoring aligned to business needs, then verify the configured limit with an owner-approved bounded test."),
  ("stop_condition", "The export sandbox slows down after two requests, below the agreed ceiling. What should happen?", "Pause immediately despite remaining request allowance, note request times and observed latency, and notify the monitoring contact. The rate ceiling is a maximum, not permission to continue through degradation. Resume only after the owner confirms stability and a revised plan."),
 ]),
]

def write_split(name, families):
    out = HERE / f"{name}.jsonl"
    with out.open("w") as f:
        for family, fixture, urls, examples in families:
            for index, (task, user, answer) in enumerate(examples, 1):
                record = {"messages":[{"role":"user","content":user},{"role":"assistant","content":answer}],"metadata":{"source_repo":"original synthetic authorized-lab corpus","source_urls":urls,"fixture_id":fixture,"scenario_family":family,"source_record":f"{fixture}:{index:02d}","license":"original authored material","topic":"pentest_methodology","task_type":task,"review_status":"source_checked_synthetic_fixture","split_group":family,"split":name}}
                f.write(json.dumps(record, ensure_ascii=False) + "\n")
    return out

train = write_split("train", FAMILIES[:6])
eval_file = write_split("eval", FAMILIES[6:])
all_rows = [json.loads(line) for p in [train, eval_file] for line in p.read_text().splitlines()]
assert len(all_rows) == 40
assert len({r["messages"][0]["content"] for r in all_rows}) == 40
assert len({r["messages"][1]["content"] for r in all_rows}) == 40
assert not ({r["metadata"]["split_group"] for r in all_rows if r["metadata"]["split"] == "train"} & {r["metadata"]["split_group"] for r in all_rows if r["metadata"]["split"] == "eval"})
assert all("<think>" not in json.dumps(r) and "tool_calls" not in json.dumps(r) for r in all_rows)
print("train", 30, "eval", 10, "families", len(FAMILIES))
